//! Counterexamples are chosen from the source/target semantics, not generated by
//! the implementation. Round-trip equality alone cannot establish these claims.
mod support;
use musicxml_midi2_convert::{
    self as convert, clip, model::RenderingPolicy, piano, remarks, rules, xml,
};
use rstest::rstest;
fn source(instrument: &str, attributes: &str, content: &str) -> Vec<u8> {
    format!("<score-partwise version=\"4.0\"><part-list><score-part id=\"P\"><part-name>{instrument}</part-name></score-part></part-list><part id=\"P\"><measure number=\"1\"><attributes><divisions>4</divisions></attributes><note {attributes}><pitch><step>C</step><octave>4</octave></pitch><duration>4</duration>{content}</note></measure></part></score-partwise>").into_bytes()
}
#[rstest]
#[case("", "<type>64th</type>", 0x10, 0)] // Written type is not sounding duration.
#[case("dynamics=\"140\"", "<type>64th</type>", 0x10, 0)] // Loud+fast does not prove bounce.
#[case("attack=\"2\"", "", 0x10, 0)] // Late attack does not assert a damped release.
#[case("release=\"-2\"", "", 0x10, 0)] // Gate shortening does not establish sampled production.
#[case("release=\"2\"", "", 0x10, 0)]
#[case("release=\"-0.01\"", "", 0x10, 0)]
#[case(
    "release=\"-2\"",
    "<notations><articulations><strong-accent/></articulations></notations>",
    0x10,
    6
)]
#[case(
    "release=\"-2\"",
    "<notations><articulations><tenuto/></articulations></notations>",
    0x10,
    0
)]
#[case(
    "release=\"-2\"",
    "<notations><articulations><staccatissimo/></articulations></notations>",
    0x11,
    4
)]
#[case(
    "",
    "<notations><technical><double-tongue/></technical></notations>",
    0x10,
    0
)]
#[case(
    "",
    "<notations><technical><triple-tongue/></technical></notations>",
    0x10,
    0
)]
fn context_does_not_prove_a_more_specific_production(
    #[case] attrs: &str,
    #[case] notation: &str,
    #[case] at: u8,
    #[case] sub: u8,
) {
    let input = source("Violin", attrs, notation);
    let c = convert::xml_to_midi2(&input, &RenderingPolicy::default()).unwrap();
    let d = clip::decode(&c.clip, Some(&c.companion.dictionary)).unwrap();
    assert_eq!(d.notes.len(), 1);
    assert_eq!(
        (d.notes[0].articulation.at, d.notes[0].articulation.subclass),
        (at, sub)
    );
    let canonical = xml::write(&d).unwrap();
    if notation.contains("tongue") {
        assert!(canonical.contains(if notation.contains("double") {
            "<double-tongue"
        } else {
            "<triple-tongue"
        }));
    }
    let (_, back) = xml::read(canonical.as_bytes(), &RenderingPolicy::default()).unwrap();
    let (bytes, map, _) = clip::encode(&back).unwrap();
    assert_eq!(
        d.semantic_values(),
        clip::decode(&bytes, Some(&map)).unwrap().semantic_values()
    );
}
#[rstest]
#[case("Violin")]
#[case("Flute")]
#[case("Trumpet")]
#[case("Snare Drum")]
#[case("Timpani")]
#[case("Guitar")]
#[case("Harp")]
#[case("Organ")]
#[case("Choir")]
fn every_named_sound_remains_reachable_across_the_appendix_instrument_columns(
    #[case] instrument: &str,
) {
    // M2-123 Appendix A explicitly forbids treating its applicability hints as
    // mandatory restrictions. In particular naturally decaying percussion is not
    // automatically staccato. These are nine printed columns, despite §2 saying eight.
    for row in rules::VOCABULARY {
        let input = source(
            instrument,
            "",
            &format!(
                "<notations><technical><other-technical>{}</other-technical></technical></notations>",
                xml::escape(row.term)
            ),
        );
        let c = convert::xml_to_midi2(&input, &RenderingPolicy::default()).unwrap();
        let d = clip::decode(&c.clip, Some(&c.companion.dictionary)).unwrap();
        assert_eq!(
            (d.notes[0].articulation.at, d.notes[0].articulation.subclass),
            (row.at, row.sub),
            "{instrument}: {}",
            row.id
        );
        let canonical = xml::write(&d).unwrap();
        assert!(canonical.contains(instrument));
        let (_, back) = xml::read(canonical.as_bytes(), &RenderingPolicy::default()).unwrap();
        let (bytes, map, _) = clip::encode(&back).unwrap();
        assert_eq!(
            d.semantic_values(),
            clip::decode(&bytes, Some(&map)).unwrap().semantic_values(),
            "{instrument}: {}",
            row.id
        );
    }
}
