#[test]
fn musicxml_shake_is_an_ornament_schedule_not_automatically_a_brass_shake_sample() {
    let (_, p) = xml::read(
        &source(
            "Trumpet",
            "",
            "<notations><ornaments><shake/></ornaments></notations>",
        ),
        &RenderingPolicy::default(),
    )
    .unwrap();
    assert_eq!(
        p.notes
            .iter()
            .map(|n| n.pitch.to_integer())
            .collect::<Vec<_>>(),
        [60, 62, 60]
    );
    assert_eq!(
        p.notes.iter().map(|n| n.onset).collect::<Vec<_>>(),
        [
            0.into(),
            convert::model::Rational::new(3, 25),
            convert::model::Rational::new(6, 25)
        ]
    );
    assert!(p.notes.iter().all(|n| n.articulation.at == 0x10));
}
#[test]
fn explicitly_lower_ornament_start_is_not_replaced_with_an_upper_neighbor() {
    let (_, p) = xml::read(
        &source(
            "Flute",
            "",
            "<notations><ornaments><trill-mark start-note=\"below\"/></ornaments></notations>",
        ),
        &RenderingPolicy::default(),
    )
    .unwrap();
    assert_eq!(
        p.notes
            .iter()
            .map(|n| n.pitch.to_integer())
            .collect::<Vec<_>>(),
        [58, 60, 58, 60]
    );
}
#[test]
fn a_touching_harmonic_pitch_is_not_sounded_as_if_it_were_the_resulting_partial() {
    let e=xml::read(&source("Violin","","<notations><technical><harmonic><artificial/><touching-pitch/></harmonic></technical></notations>"),&RenderingPolicy::default()).unwrap_err();
    assert_eq!(e.code, "E_HARMONIC_PITCH");
}
#[test]
fn scoped_other_ornament_remains_literal_and_does_not_invent_a_library_articulation() {
    let input = source(
        "Harp",
        "",
        "<voice>2</voice><notations><ornaments><other-ornament>irregular glass shimmer</other-ornament></ornaments></notations>",
    );
    let c = convert::xml_to_midi2(&input, &RenderingPolicy::default()).unwrap();
    let d = clip::decode(&c.clip, Some(&c.companion.dictionary)).unwrap();
    assert_eq!(d.notes.len(), 1);
    assert_eq!(d.notes[0].articulation, rules::Articulation::default());
    let descriptor = d.notes[0].descriptor.as_ref().unwrap();
    assert_eq!(
        remarks::literal_values(descriptor),
        ["irregular glass shimmer"]
    );
    assert_eq!(descriptor.qualifiers[remarks::QUALIFIER][0]["voice"], "2");
    let canonical = xml::write(&d).unwrap();
    assert!(canonical.contains("<other-ornament>irregular glass shimmer</other-ornament>"));
    support::assert_schema(
        &[canonical.as_bytes()],
        std::path::Path::new("other-ornament inverse"),
    );
    let (_, back) = xml::read(canonical.as_bytes(), &RenderingPolicy::default()).unwrap();
    let (bytes, map, _) = clip::encode(&back).unwrap();
    assert_eq!(
        d.semantic_values(),
        clip::decode(&bytes, Some(&map)).unwrap().semantic_values()
    );
}
#[test]
fn left_hand_pizzicato_glyph_requests_plucking_as_well_as_direction() {
    let (_,s)=xml::read(&source("Violin","","<notations><technical><other-technical smufl=\"pluckedLeftHandPizzicato\"/></technical></notations>"),&RenderingPolicy::default()).unwrap();
    assert_eq!(
        (
            s.notes[0].articulation.at,
            s.notes[0].articulation.subclass,
            s.notes[0].articulation.direction
        ),
        (0x11, 10, 2)
    );
}

#[rstest]
#[case("stress", true)]
#[case("unstress", false)]
#[case("soft-accent", false)]
fn relative_attack_marks_change_emphasis_but_never_override_authored_velocity(
    #[case] mark: &str,
    #[case] more: bool,
) {
    let plain = xml::read(&source("Flute", "", ""), &RenderingPolicy::default())
        .unwrap()
        .1;
    let native = format!("<notations><articulations><{mark}/></articulations></notations>");
    let c =
        convert::xml_to_midi2(&source("Flute", "", &native), &RenderingPolicy::default()).unwrap();
    let d = clip::decode(&c.clip, Some(&c.companion.dictionary)).unwrap();
    assert_eq!(d.notes[0].velocity > plain.notes[0].velocity, more);
    assert_ne!(d.notes[0].velocity, plain.notes[0].velocity);
    let explicit = xml::read(
        &source("Flute", "dynamics=\"50\"", &native),
        &RenderingPolicy::default(),
    )
    .unwrap()
    .1;
    assert_eq!(explicit.notes[0].velocity, 0x5a00);
    let canonical = xml::write(&d).unwrap();
    assert!(canonical.contains(&format!("<{mark}")));
    let (_, back) = xml::read(canonical.as_bytes(), &RenderingPolicy::default()).unwrap();
    let (bytes, map, _) = clip::encode(&back).unwrap();
    assert_eq!(
        d.semantic_values(),
        clip::decode(&bytes, Some(&map)).unwrap().semantic_values()
    );
}

#[test]
fn repeated_freehand_notation_keeps_provenance_without_duplicate_xml_ids() {
    let input=String::from_utf8(source("Violin","","<notations><other-notation id=\"color\" type=\"single\">Nearly inaudible air texture</other-notation></notations>")).unwrap().replace("</measure>","<barline><repeat direction=\"backward\"/></barline></measure>");
    let c = convert::xml_to_midi2(input.as_bytes(), &RenderingPolicy::default()).unwrap();
    let d = clip::decode(&c.clip, Some(&c.companion.dictionary)).unwrap();
    assert_eq!(d.notes.len(), 2);
    assert!(d.notes.iter().all(|n| {
        n.descriptor.as_ref().unwrap().qualifiers[remarks::QUALIFIER][0]["xml"]
            .as_str()
            .unwrap()
            .contains("id=\"color\"")
    }));
    let canonical = xml::write(&d).unwrap();
    support::assert_schema(
        &[canonical.as_bytes()],
        std::path::Path::new("repeated remark inverse"),
    );
    let doc = roxmltree::Document::parse(&canonical).unwrap();
    assert_eq!(
        doc.descendants()
            .filter(|n| n.has_tag_name("other-notation"))
            .count(),
        2
    );
    assert!(
        !doc.descendants()
            .any(|n| n.has_tag_name("other-notation") && n.attribute("id").is_some())
    );
    let (_, back) = xml::read(canonical.as_bytes(), &RenderingPolicy::default()).unwrap();
    let (bytes, map, _) = clip::encode(&back).unwrap();
    assert_eq!(
        d.semantic_values(),
        clip::decode(&bytes, Some(&map)).unwrap().semantic_values()
    );
}

#[rstest]
#[case("start", 0)]
#[case("stop", 0)]
#[case("start", 3)]
#[case("stop", 3)]
fn a_paired_tremolo_is_not_misread_as_two_single_note_rolls(#[case] kind: &str, #[case] marks: u8) {
    let input = source(
        "Violin",
        "",
        &format!(
            "<notations><ornaments><tremolo type=\"{kind}\">{marks}</tremolo></ornaments></notations>"
        ),
    );
    assert_eq!(
        xml::read(&input, &RenderingPolicy::default())
            .unwrap_err()
            .code,
        "E_PATTERN_BINDING"
    );
}
#[rstest]
#[case(0)]
#[case(3)]
fn an_explicit_unmeasured_tremolo_is_not_given_an_invented_measured_rate(#[case] marks: u8) {
    let input = source(
        "Violin",
        "",
        &format!(
            "<notations><ornaments><tremolo type=\"unmeasured\">{marks}</tremolo></ornaments></notations>"
        ),
    );
    let (_, p) = xml::read(&input, &RenderingPolicy::default()).unwrap();
    assert_eq!(p.notes.len(), 1);
    assert_eq!(
        (p.notes[0].articulation.at, p.notes[0].articulation.subclass),
        (0x12, 0)
    );
    assert!(xml::write(&p).unwrap().contains("type=\"unmeasured\""));
}
